<style id="wp-custom-css">
/*Remove Highlight Color on Click */
* {
  -webkit-tap-highlight-color: transparent;
}

/* Set text highlight color to #26AFAF */
::-moz-selection {
    background-color: #704B4170;
    color: #fff; /* Set the text color inside the selection for Firefox */
}

::selection {
    background-color: #704B4170;
    color: #fff; /* Set the text color inside the selection for other browsers */
}

.scroll-offset {
    padding-top: 30vh; /* Adjust this value to suit your layout */
    margin-top: -30vh; /* Adjust this value to be the negative of padding-top */
}

html {
    scroll-behavior: smooth;
}

*:focus,
*:active {
    outline: none;
}

/* Remove default browser focus outline for all focusable elements */
:focus {
    outline: none;
}

/* Hide scrollbar for all browsers */
html {
    overflow: -moz-scrollbars-none; /* Firefox */
    -ms-overflow-style: none; /* Internet Explorer and Edge */
}

body {
    overflow-y: scroll; /* Always show vertical scrollbar */
}

/* Hide scrollbar for WebKit browsers (Chrome, Safari) */
body::-webkit-scrollbar {
    display: none; /* Hides scrollbar */
}

/* Allow scrolling */
body {
    overflow-y: scroll; /* Enable vertical scrolling */
}

html {
  max-width: 100%;
}

body {
  max-width: 100%;
  position: relative;
}

/* Safer horizontal containment without breaking scroll-lock / pin animations */
#page,
.site,
.elementor,
.elementor-location-body {
  width: 100%;
  max-width: 100%;
  overflow-x: clip;
}

@supports not (overflow: clip) {
  #page,
  .site,
  .elementor,
  .elementor-location-body {
    overflow-x: hidden;
  }
}

img,
video,
svg,
canvas {
  max-width: 100%;
}
</style>
<style>

/* =========================
KHUFUS — CONTACT HERO
USING EXPERIENCE HERO LAYOUT
========================= */

@font-face{
  font-family:"IvyOraDisplay";
  src:url("/assets/images/IvyOraDisplay-Light.woff2") format("woff2");
  font-weight:300;
  font-style:normal;
  font-display:swap;
}

@font-face{
  font-family:"GoldenHopes";
  src:url("/assets/images/GoldenHopes.woff2") format("woff2");
  font-weight:400;
  font-style:normal;
  font-display:swap;
}

@import url("https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@300;400&display=swap");

.kh-gallery-hero,
.kh-gallery-hero *{
  box-sizing:border-box;
}

.kh-gallery-hero{
  position:relative;
  width:100%;
  height:100svh;
  display:flex;
  align-items:flex-end;
  overflow:hidden;
  isolation:isolate;

  background:
  linear-gradient(
    180deg,
    rgba(92,71,43,0.35) 0%,
    rgba(92,71,43,0.55) 25%,
    rgba(92,71,43,0.75) 50%,
    rgba(92,71,43,0.9) 75%,
    rgba(92,71,43,1) 100%
  ),
  url("/assets/ai_ganerated/images/contact_page_hero_section.png")
  center center / cover no-repeat;

}

.kh-gallery-hero-inner{
  width:100%;
  padding:60px;
  display:grid;
  grid-template-columns:minmax(0,1fr) minmax(260px,340px);
  gap:40px;
  align-items:end;
  position:relative;
  z-index:2;
}

/* =========================
LEFT COLUMN
========================= */

.kh-gallery-hero-copy{
  max-width:720px;
}

.kh-gallery-hero-kicker{
  margin-bottom:16px;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:11px;
  letter-spacing:.26em;
  text-transform:uppercase;
  color:rgba(247,243,238,.65);
}

.kh-gallery-hero-title{
  margin:0;
  font-family:"IvyOraDisplay",serif;
  font-weight:300;
  font-size:56px;
  line-height:1.05;
  letter-spacing:.01em;
  color:#F7F3EE;
  text-transform:uppercase;
  position:relative;
  padding-bottom:0px; /* increased space for script */
}

.kh-gallery-hero-script{
  position:absolute;
  left:10px;
  bottom:-28px; /* pushed slightly further down */
  font-family:"GoldenHopes",cursive;
  font-size:30px;
  color:#F2E4C7;
  letter-spacing:.04em;
  transform:rotate(-2deg);
  text-transform:capitalize;
  pointer-events:none;
  padding-bottom: 10px;
}

.kh-gallery-hero-lead{
  margin-top:36px;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:14px;
  line-height:1.8;
  color:rgba(247,243,238,.75);
  font-weight:300;
  max-width:520px;
}

.kh-gallery-hero-scroll{
  margin-top:28px;
  display:flex;
  align-items:center;
  gap:10px;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:10px;
  letter-spacing:.26em;
  text-transform:uppercase;
  color:rgba(247,243,238,.62);
}

.kh-gallery-hero-scroll-line{
  width:46px;
  height:1px;
  background:rgba(247,243,238,.35);
}

/* =========================
RIGHT COLUMN
========================= */

.kh-gallery-hero-side{
  width:100%;
  max-width:300px;
  margin-left:auto;
  border-top:1px solid rgba(255,255,255,.14);
  padding-top:16px;
  text-align:right;
