.kh-gallery-hero-side p{
  margin:0;
  font-family:"Bricolage Grotesque",sans-serif;
  font-size:13px;
  line-height:1.75;
  color:rgba(247,243,238,.65);
  font-weight:300;
}

/* =========================
ANIMATION
========================= */

.kh-gallery-hero-reveal{
  opacity:0;
  transform:translateY(30px);
  transition:
    opacity .9s cubic-bezier(.22,1,.36,1),
    transform .9s cubic-bezier(.22,1,.36,1);
}

.kh-gallery-hero-reveal.show{
  opacity:1;
  transform:translateY(0);
}

/* =========================
RESPONSIVE
========================= */

@media(max-width:900px){
  .kh-gallery-hero-inner{
    grid-template-columns:1fr;
    padding:30px 30px;
    gap:24px;
  }

  .kh-gallery-hero-side{
