    bottom:-32px;
    left: 0px;
  }

  .kh-gallery-hero-lead{
    font-size:12px;
    line-height:1.6; /* tighter */
  }
  
  .kh-gallery-hero-kicker{
    font-size:9px; /* was 11px */
    letter-spacing:.22em;
  }
}

</style>
