<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" type="text/javascript"></script>

<script type="text/javascript">
(function(){

  var mapEl = document.getElementById("kh-map");
  if(!mapEl) return;

  var locations = [
    { name: "Dublin", lat: 37.704563, lng: -121.87544, address: "4288 Dublin Blvd #111, Dublin, CA 94568", phone: "(925) 361-5317", url: "https://google.com/maps/place?q=Biryani%20and%20Dosa%20Grill%2C%204288%20Dublin%20Blvd%20%23111%2C%20Dublin%2C%20CA%2094568" },
    { name: "Milpitas", lat: 37.425353, lng: -121.905125, address: "380 South Main Street, Milpitas, CA 95035", phone: "(669) 264-7920", url: "https://google.com/maps/place?q=Biryani%20and%20Dosa%20Grill%2C%20380%20South%20Main%20Street%2C%20Milpitas%2C%20CA%2095035" },
    { name: "Livermore", lat: 37.69143, lng: -121.773786, address: "2050 Portola Avenue, Livermore, CA 94551", phone: "(669) 264-7920", url: "https://google.com/maps/place?q=Biryani%20and%20Dosa%20Grill%2C%202050%20Portola%20Avenue%2C%20Livermore%2C%20CA%2094551" },
    { name: "Concord", lat: 37.970282, lng: -122.011414, address: "3540 Clayton Road, Concord, CA 94519", phone: "(925) 494-4470", url: "https://google.com/maps/place?q=Biryani%20and%20Dosa%20Grill%2C%203540%20Clayton%20Road%2C%20Concord%2C%20CA%2094519" }
  ];

  var map = L.map(mapEl,{
    zoomControl:false,
    attributionControl:false,
    scrollWheelZoom:false,
    dragging:true,
    touchZoom:true,
    doubleClickZoom:false,
    boxZoom:false,
    keyboard:false
  }).setView([37.704563, -121.87544], 10);

  L.tileLayer(
    "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
  ).addTo(map);

  var pinIcon = L.divIcon({
    className:"",
    html: `
      <div class="kh-leaflet-pin">
        <span class="kh-leaflet-pin-pulse"></span>
        <span class="kh-leaflet-pin-dot"></span>
        <span class="kh-leaflet-pin-core"></span>
      </div>
    `,
    iconSize:[28,28],
    iconAnchor:[14,14]
  });

  locations.forEach(function(loc){
    var marker = L.marker([loc.lat, loc.lng],{
      icon:pinIcon
    }).addTo(map);

    marker.bindPopup(`
      <div style="font-family:sans-serif;font-size:13px;color:#1A1009;padding:4px;">
        <strong style="font-size:14px;">${loc.name}</strong><br>
        <span>${loc.address}</span><br>
        <span>${loc.phone}</span><br>
        <a href="${loc.url}" target="_blank" rel="noopener" style="color:#8C6239;font-weight:600;display:inline-block;margin-top:4px;">View on Google Maps</a>
      </div>
    `);
  });

  function fixMap(){
    setTimeout(function(){
      map.invalidateSize();
    },60);
    setTimeout(function(){
      map.invalidateSize();
    },300);
  }

  fixMap();
  window.addEventListener("resize",fixMap);
  window.addEventListener("load",fixMap);

})();
</script>				</div>
